use lightog_core::{source_execution_v1 as e,common::canonical_hash as hash};use serde_json::{json,Value};
fn scope(op:&str)->Value{json!({"version":"lightog-source-product-budget/1","input":{"sources":[]},"context":{"operation":op,"question":"What does Nova do?","proposal_policy_version":"source-learning-product-candidate-mvp-v1"},"source_stamp":{"base_id":"kb_nova","source_epoch":0},"snapshot":{"base_ref":"kb_nova","source_epoch":0,"graph_revision":null,"sources":[]},"models":{"generation":{"model":"authored","config_revision":1},"embedding":{"model":"embed","config_revision":1},"reranker":{"model":"rank","config_revision":1}}})}
fn issue(s:&Value)->Value{e::execute("create",&json!({"contract_version":e::VERSION,"scope":s,"execution_key":"authored-request","embedding_plan":{"scope_sha256":hash(s),"status":"READY","point_in_time_only":true,"document_batches":2,"query_batches":1}})).unwrap()}
fn reserve(c:&Value,s:&Value,phase:&str,id:&str,cap:&str,obs:Value)->Value{e::execute("reserve",&json!({"contract_version":e::VERSION,"execution":c,"scope":s,"call":{"phase":phase,"request_id":id,"capability":cap,"text_count":20,"max_tokens":5000},"observations":obs,"index_plan":null,"job":null})).unwrap()}
#[test]fn automatic_ask_is_finite_derived_plan_without_user_limits(){let s=scope("ASK");let c=issue(&s);assert!(c.get("limits").is_none());assert_eq!(c["user_quota"],false);assert_eq!(c["phase_plan"]["SOURCE_DOCUMENT_EMBEDDING"]["planned_calls"],2);let r=reserve(&c,&s,"SOURCE_DOCUMENT_EMBEDDING","doc0","embedding",json!([]));assert_eq!(r["execution"]["used"]["embedding"],1);let r2=reserve(&r["execution"],&s,"SOURCE_DOCUMENT_EMBEDDING","doc1","embedding",json!([{"request_id":"doc0","outcome":"COMPLETED"}]));let p=json!({"contract_version":e::VERSION,"execution":r2["execution"],"scope":s,"call":{"phase":"SOURCE_DOCUMENT_EMBEDDING","request_id":"doc2","capability":"embedding","text_count":20},"observations":[{"request_id":"doc0","outcome":"COMPLETED"},{"request_id":"doc1","outcome":"COMPLETED"}]});assert_eq!(e::execute("reserve",&p).unwrap_err().code,"SOURCE_EXECUTION_PHASE_PLAN_EXHAUSTED");}
#[test]fn missing_unknown_or_reused_outcome_cannot_authorize_resend(){let s=scope("ASK");let r=reserve(&issue(&s),&s,"ANSWER_GENERATION","one","generation",json!([]));for obs in [json!([]),json!([{"request_id":"one","outcome":"STARTED"}]),json!([{"request_id":"one","outcome":"UNKNOWN"}])]{let p=json!({"contract_version":e::VERSION,"execution":r["execution"],"scope":s,"call":{"phase":"ANSWER_REVIEW","request_id":"two","capability":"generation","max_tokens":8000},"observations":obs});assert_eq!(e::execute("reserve",&p).unwrap_err().code,"SOURCE_EXECUTION_PRIOR_OUTCOME_UNKNOWN_NO_RESEND");}let p=json!({"contract_version":e::VERSION,"execution":r["execution"],"scope":s,"call":{"phase":"ANSWER_REVIEW","request_id":"one","capability":"generation","max_tokens":8000},"observations":[{"request_id":"one","outcome":"RETURNED"}]});assert_eq!(e::execute("reserve",&p).unwrap_err().code,"SOURCE_EXECUTION_REQUEST_ALREADY_RESERVED_NO_RESEND");}
#[test]fn source_model_or_execution_tamper_rejected(){let s=scope("ASK");let c=issue(&s);for kind in 0..3{let mut changed=s.clone();if kind==0{changed["source_stamp"]["source_epoch"]=json!(1)}else if kind==1{changed["models"]["generation"]["config_revision"]=json!(2)}else{changed["context"]["question"]=json!("other")}assert!(e::execute("validate",&json!({"contract_version":e::VERSION,"execution":c,"scope":changed})).is_err());}let mut c=c;c["phase_plan"]["ANSWER_GENERATION"]["planned_calls"]=json!(999999);assert!(e::execute("validate",&json!({"contract_version":e::VERSION,"execution":c,"scope":s})).is_err());}
#[test]fn index_calls_derived_from_persisted_actual_batches_not_an_arbitrary_quota(){let s=scope("SOURCE_LEARNING");let c=issue(&s);let p=json!({"contract_version":e::VERSION,"execution":c,"scope":s,"call":{"phase":"INDEX_DOCUMENT_EMBEDDING_001","request_id":"index1","capability":"embedding","text_count":1},"observations":[],"index_plan":{"all_texts_sha256":"a".repeat(64),"batches":[["first"],["second"]]},"job":{"stage":"INDEX_PENDING","snapshot":s["snapshot"],"request":{"raw_question":s["context"]["question"],"policy_version":s["context"]["proposal_policy_version"]},"attempts":[{"outcome":"RETURNED"}]}});let r=e::execute("reserve",&p).unwrap();assert_eq!(r["execution"]["phase_plan"]["INDEX_DOCUMENT_EMBEDDING_001"]["planned_calls"],1);let mut bad=p;bad["call"]["phase"]=json!("INDEX_DOCUMENT_EMBEDDING_002");assert_eq!(e::execute("reserve",&bad).unwrap_err().code,"SOURCE_EXECUTION_INDEX_PLAN_INVALID");}
#[test]fn learning_admission_distinguishes_graph_unknown_from_answer_gap_and_obeys_source(){let snapshot=json!({"base_ref":"kb_nova","source_epoch":0,"sources":[]});let mut p=json!({"contract_version":e::VERSION,"current_snapshot":snapshot,"response":{"status":"ANSWERED","provider_outcome_unknown":false,"answer":{"snapshot":snapshot,"question":"Nova?","coverage_scope":"RETRIEVED_SOURCE_FRAGMENTS_ONLY","verification":{"reviewed":true},"gaps":[],"statements":[{"evidence_ids":["source1"]}],"requirement_coverage":[{"decision":"COVERED"}]},"retrieval_trace":{"record_decisions":[]}}});let r=e::execute("learning_admission",&p).unwrap();assert_eq!(r["reason"],"GRAPH_COVERAGE_UNKNOWN");assert_eq!(r["semantic_gap_certified"],false);p["response"]["retrieval_trace"]["record_decisions"]=json!([{"record_id":"profile:nova","reason":"COVERED_LINK","evidence_ids":["source1"]}]);assert_eq!(e::execute("learning_admission",&p).unwrap()["enqueue_discovery"],false);p["response"]["answer"]["gaps"]=json!(["An original answer gap"]);assert_eq!(e::execute("learning_admission",&p).unwrap()["reason"],"ANSWER_COVERAGE_GAP");p["current_snapshot"]["source_epoch"]=json!(1);assert_eq!(e::execute("learning_admission",&p).unwrap()["enqueue_discovery"],false);}
#[test]fn batched_generation_extends_only_from_exact_rust_source_partition(){let text="Nova background information.\n".repeat(1000);let digest=lightog_core::common::text_sha(&text);let mut s=scope("SOURCE_LEARNING");s["context"]["proposal_policy_version"]=json!("source-learning-product-candidate-mvp-batched-v1");s["snapshot"]["sources"]=json!([{"source_ref":"src","source_revision":"r1","text_sha256":digest,"original_sha256":digest,"parser_version":"authored/1"}]);let n=text.encode_utf16().count();let es=json!({"contract_version":"lightog-demand/0.1","evidence_set_id":"source_all","snapshot":s["snapshot"],"fragments":[{"id":"whole","origin":"SOURCE_FRAGMENT","source_ref":"src","source_revision":"r1","block_ref":"block","text_sha256":digest,"span":{"start":0,"end":n,"quote":text,"offset_unit":"utf16_code_unit"},"claim_refs":[],"role":"PRIMARY"}]});let ctx=json!({"examples":{"source_all":es},"source_texts":[{"source_ref":"src","source_revision":"r1","text":text,"original_sha256":digest,"parser_version":"authored/1","blocks":[{"block_ref":"block","start":0,"end":n}]}],"authority":{"requests":[],"allowed_snapshots":[s["snapshot"]],"claims":[],"receipts":[],"scope_bindings":[],"entities":[],"predicate_refs":[],"user_definitions":[],"groups":[],"entity_links":[]}});let plan=lightog_core::fine_source_evidence::execute("refine_batches",&json!({"contract_version":"lightog-fine-source-evidence/0.1","evidence_set":es,"context":ctx})).unwrap();assert!(plan["batches"].as_array().unwrap().len()>1);let c=issue(&s);assert!(c["phase_plan"].as_object().unwrap().is_empty());let p=json!({"contract_version":e::VERSION,"execution":c,"scope":s,"call":{"phase":"EXTRACTION_000","request_id":"page0","capability":"generation","max_tokens":6000},"observations":[],"extraction_plan":plan,"extraction_context":ctx,"job":{"stage":"EXTRACTING","snapshot":s["snapshot"],"request":{"raw_question":s["context"]["question"],"policy_version":s["context"]["proposal_policy_version"]},"evidence_set":es,"attempts":[]}});let first=e::execute("reserve",&p).unwrap();assert_eq!(first["execution"]["phase_plan"]["EXTRACTION_001"]["planned_calls"],1);let mut next=p.clone();next["execution"]=first["execution"].clone();next["call"]["phase"]=json!("EXTRACTION_001");next["call"]["request_id"]=json!("page1");next["observations"]=json!([{"request_id":"page0","outcome":"RETURNED"}]);next["job"]["attempts"]=json!([{"outcome":"RETURNED"}]);assert!(e::execute("reserve",&next).is_ok());next["extraction_plan"]["batches"][0]["evidence_set"]["fragments"][0]["span"]["quote"]=json!("not original");assert!(e::execute("reserve",&next).is_err());}
#[test]
fn automatic_generation_uses_provider_capacity_without_application_output_quota(){
 let s=scope("ASK");let c=issue(&s);
 assert_eq!(c["generation_output_policy"],"PROVIDER_DEFAULT");assert!(c["phase_plan"]["ANSWER_GENERATION"]["max_output_tokens"].is_null());
 let p=json!({"contract_version":e::VERSION,"execution":c,"scope":s,"call":{"phase":"ANSWER_GENERATION","request_id":"provider_default","capability":"generation","max_tokens":null},"observations":[]});
 assert!(e::execute("reserve",&p).is_ok());
 let mut explicit=p.clone();explicit["call"]["max_tokens"]=json!(131072);assert!(e::execute("reserve",&explicit).is_ok());
 let mut invalid=p;invalid["call"]["max_tokens"]=json!(-1);assert!(e::execute("reserve",&invalid).is_err());
}
#[test]
fn legacy_execution_output_limit_remains_bound_to_its_original_receipt(){
 let s=scope("ASK");let mut c=issue(&s);c.as_object_mut().unwrap().remove("generation_output_policy");c["phase_plan"]["ANSWER_GENERATION"]["max_output_tokens"]=json!(5000);c.as_object_mut().unwrap().remove("record_sha256");c["record_sha256"]=json!(hash(&c));
 let mut p=json!({"contract_version":e::VERSION,"execution":c,"scope":s,"call":{"phase":"ANSWER_GENERATION","request_id":"legacy","capability":"generation","max_tokens":null},"observations":[]});
 assert!(e::execute("reserve",&p).is_err());p["call"]["max_tokens"]=json!(5000);assert!(e::execute("reserve",&p).is_ok());p["call"]["max_tokens"]=json!(6000);assert!(e::execute("reserve",&p).is_err());
}
